#!/usr/bin/env python3"""Fix collapsed line 743 in prompts.py - byte-level approach."""from pathlib import Pathtarget = Path("bin/agent/prompts.py")raw = target.read_bytes()# Find the start marker and end markerstart_marker = b'def _serialize_element(elem: ET.Element, indent: str = "") -> str:'end_marker = b'def _read_tree(path: Path) -> ET.ElementTree:'start_idx = raw.find(start_marker)end_idx = raw.find(end_marker)if start_idx == -1:    print("ERROR: start marker not found")    exit(1)if end_idx == -1:    print("ERROR: end marker not found")    exit(1)print(f"Start index: {start_idx}")print(f"End index: {end_idx}")print(f"Collapsed block size: {end_idx - start_idx} bytes")# Build the replacementreplacement = b'''def _serialize_element(elem: ET.Element, indent: str = "") -> str:    """Serialize an Element to XML string with CDATA for value elements."""    parts: list[str] = []    tag = elem.tag    attrs = ""    for k, v in elem.attrib.items():        attrs += f\' {k}="{v}"\'    children = list(elem)    has_children = len(children) > 0    if tag == "value" and elem.text:        parts.append(f"{indent}<{tag}{attrs}><![CDATA[{elem.text}]]></{tag}>")        return "".join(parts)    if not has_children and (elem.text is None or not elem.text.strip()):        parts.append(f"{indent}<{tag}{attrs} />")    elif not has_children:        parts.append(f"{indent}<{tag}{attrs}>{elem.text or \'\'}</{tag}>")    else:        parts.append(f"{indent}<{tag}{attrs}>")        for child in children:            parts.append("\\n")            parts.append(_serialize_element(child, indent + "  "))        parts.append(f"\\n{indent}</{tag}>")    return "".join(parts)def _write_prompts_xml(tree: ET.ElementTree, target: Path) -> None:    """Write the prompts XML tree to target using CDATA for value elements."""    root = tree.getroot()    xml_str = \'<?xml version="1.0" encoding="UTF-8"?>\\n\'    xml_str += _serialize_element(root)    xml_str += "\\n"    target.write_text(xml_str, encoding="utf-8")'''# Replace everything from start_marker up to (but not including) end_markernew_raw = raw[:start_idx] + replacement + raw[end_idx:]target.write_bytes(new_raw)print(f"SUCCESS: replaced {end_idx - start_idx} bytes with {len(replacement)} bytes")print(f"New file size: {len(new_raw)} bytes")